def count_pairs(n):
    import math
    g = 2023
    # 2023 = 7 * 17^2
    # Check if g divides n!
    # exponent of prime p in n! is sum(n // p^k)
    def get_exp(n, p):
        count = 0
        while n > 0:
            count += n // p
            n //= p
        return count

    if get_exp(n, 7) < 1 or get_exp(n, 17) < 2:
        return 0

    # L = n!, g = 2023.
    # We need number of pairs (a,b) such that gcd(a,b)=g, lcm(a,b)=L
    # This is 2^k where k is number of distinct prime factors of L/g.
    # L/g = n! / 2023.
    # The distinct prime factors of L/g are all primes p <= n
    # EXCEPT those p for which the exponent of p in n! equals the exponent of p in g.

    # Exponents in g: 7^1, 17^2
    # Prime factors of L/g:
    # p <= n and (p != 7 or get_exp(n, 7) > 1) and (p != 17 or get_exp(n, 17) > 2)

    primes = []
    for i in range(2, n + 1):
        is_prime = True
        for p in primes:
            if i % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(i)

    k = 0
    for p in primes:
        if p == 7:
            if get_exp(n, 7) > 1:
                k += 1
        elif p == 17:
            if get_exp(n, 17) > 2:
                k += 1
        else:
            k += 1

    return 2**k

results = []
for n in range(1, 100):
    count = count_pairs(n)
    if count <= 4000:
        results.append(n)

print(f"n values: {results}")
print(f"sum of n values: {sum(results)}")
